SELECT s.id, s.course_id, s.student_id, s.attempt_no, s.status, s.start_time, s.deadline, s.submit_time, s.score, s.total_score, s.create_time, s.update_time, u.real_name AS student_name, u.user_no AS student_no, u.department AS department, c.name AS course_name, c.code AS course_code FROM exam_session s JOIN sys_user u ON u.id = s.student_id JOIN course c ON c.id = s.course_id
AND s.status <> 0
AND s.course_id = #{courseId}
AND c.teacher_id = #{teacherId}
AND (u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.user_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY s.submit_time DESC, s.id DESC

SELECT s.id, s.course_id, s.student_id, s.attempt_no, s.status, s.start_time, s.deadline, s.submit_time, s.score, s.total_score, s.create_time, s.update_time, c.name AS course_name, c.code AS course_code FROM exam_session s JOIN course c ON c.id = s.course_id
AND s.student_id = #{studentId}
AND s.course_id = #{courseId}
ORDER BY s.create_time DESC, s.id DESC
